def choose_move(observation):
    def clamp_step(v):
        return -1 if v < 0 else (1 if v > 0 else 0)

    def pos(item):
        if isinstance(item, (list, tuple)) and len(item) >= 2:
            return item[0], item[1]
        if isinstance(item, dict):
            return item.get("x", 0), item.get("y", 0)
        return 0, 0

    def get_pos(key):
        return pos(observation.get(key, (0, 0)))

    sx, sy = get_pos("self_position")
    ox, oy = get_pos("opponent_position")
    w = observation.get("grid_width", 0)
    h = observation.get("grid_height", 0)
    env = observation.get("environment_name", "")

    def move_toward(tx, ty):
        return [clamp_step(tx - sx), clamp_step(ty - sy)]

    def move_away(tx, ty):
        return [clamp_step(sx - tx), clamp_step(sy - ty)]

    def manhattan(a, b, c, d):
        return abs(a - c) + abs(b - d)

    def best_of(points, want_far=False):
        best = None
        best_score = None
        for p in points or []:
            px, py = pos(p)
            score = manhattan(sx, sy, px, py)
            if best is None or (want_far and score > best_score) or ((not want_far) and score < best_score):
                best = (px, py)
                best_score = score
        return best

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return move_toward(ox, oy)

        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        if corners:
            tx, ty = max(corners, key=lambda c: manhattan(ox, oy, c[0], c[1]))
            return move_toward(tx, ty)
        return move_away(ox, oy)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier") or []
        best = best_of(targets, want_far=False)
        if best is not None:
            return move_toward(best[0], best[1])
        if w and h:
            return move_toward(w // 2, h // 2)
        return move_toward(ox, oy)

    resources = observation.get("resources") or observation.get("resource_positions") or []
    best = best_of(resources, want_far=False)
    if best is not None:
        return move_toward(best[0], best[1])

    if w and h:
        return move_toward(w // 2, h // 2)

    return move_away(ox, oy)

